mapper.update:
UPDATE auth_token
SET csrf=#{csrf}
WHERE token_hash=#{tokenHash}

mapper.delete:
DELETE
FROM auth_token
WHERE expires_at < #{expiresBefore} OR last_seen < #{lastSeenBefore}

mapper.select:
SELECT token_hash, kind, csrf, created_at, last_seen, expires_at, attempts, revision
FROM auth_token
WHERE token_hash=#{tokenHash} AND kind=#{kind} AND expires_at>#{expiresAfter} AND last_seen>#{lastSeenAfter} AND revision=#{revision}

mapper.update:
UPDATE auth_token
SET last_seen=#{lastSeen}
WHERE token_hash=#{tokenHash}

mapper.select:
SELECT bucket, failures, blocked_until, updated_at
FROM auth_throttle
WHERE bucket=#{bucket}

mapper.delete:
DELETE
FROM auth_throttle
WHERE bucket=#{accountBucket} OR bucket=#{addressBucket}

mapper.update:
UPDATE auth_account
SET last_totp_step=#{step}
WHERE id=1 AND last_totp_step<#{previousStepLimit} AND revision=#{revision}

UPDATE auth_token
SET attempts=attempts+1
WHERE token_hash=#{tokenHash}

mapper.select:
SELECT attempts
FROM auth_token
WHERE token_hash=#{tokenHash}
